css:
.send-wrap {
  --black: #050505;
  --white: #ffffff;

  position: relative;

  width: 230px;
  height: 80px;

  display: flex;
  justify-content: center;
  align-items: center;

  font-family: Inter, system-ui, sans-serif;
}

/* ═══════════════════════════════
   CHECKBOX
═══════════════════════════════ */

.send-input {
  position: absolute;

  width: 1px;
  height: 1px;

  opacity: 0;
}

/* ═══════════════════════════════
   BUTTON
═══════════════════════════════ */

.send {
  position: relative;

  width: 215px;
  height: 60px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 18px;

  cursor: pointer;
  overflow: visible;

  color: var(--white);

  background: linear-gradient(145deg, #191919, #050505);

  border: 1px solid rgba(255, 255, 255, 0.14);

  box-shadow:
    0 15px 30px rgba(0, 0, 0, 0.35),
    inset 0 1px 0 rgba(255, 255, 255, 0.12),
    inset 0 -1px 0 rgba(0, 0, 0, 0.8);

  transition:
    transform 0.3s cubic-bezier(0.2, 0.9, 0.2, 1),
    box-shadow 0.3s ease;
}

/* borde luminoso */

.send::before {
  content: "";

  position: absolute;
  inset: -1px;

  border-radius: inherit;

  background: linear-gradient(
    120deg,
    rgba(255, 255, 255, 0.35),
    transparent 25%,
    transparent 70%,
    rgba(255, 255, 255, 0.18)
  );

  opacity: 0.5;

  z-index: -1;

  transition: opacity 0.3s ease;
}

/* ═══════════════════════════════
   BRILLO
═══════════════════════════════ */

.shine {
  position: absolute;

  top: -40%;
  left: -40%;

  width: 35px;
  height: 180%;

  background: rgba(255, 255, 255, 0.18);

  filter: blur(9px);

  transform: rotate(25deg);

  transition: left 0.8s cubic-bezier(0.2, 0.8, 0.2, 1);
}

/* ═══════════════════════════════
   CONTENIDO
═══════════════════════════════ */

.send-inner {
  position: relative;
  z-index: 5;

  width: 100%;

  display: flex;
  align-items: center;

  gap: 12px;

  padding: 0 11px;
}

/* ═══════════════════════════════
   ICONO
═══════════════════════════════ */

.icon-box {
  position: relative;

  width: 38px;
  height: 38px;

  flex-shrink: 0;

  display: grid;
  place-items: center;

  border-radius: 12px;

  color: #000;
  background: #fff;

  box-shadow: 0 5px 15px rgba(0, 0, 0, 0.3);

  transition:
    transform 0.55s cubic-bezier(0.2, 1.3, 0.3, 1),
    background 0.35s ease,
    color 0.35s ease;
}

.icon-box svg {
  position: absolute;

  width: 19px;
  height: 19px;

  transition:
    transform 0.5s cubic-bezier(0.2, 1.2, 0.3, 1),
    opacity 0.3s ease;
}

/* avión */

.plane {
  transform: translate(0, 0) rotate(-10deg);
}

/* check */

.check {
  opacity: 0;

  transform: scale(0.2) rotate(-40deg);
}

/* ═══════════════════════════════
   TEXTO
═══════════════════════════════ */

.label-text {
  position: relative;

  flex: 1;

  height: 20px;

  overflow: hidden;

  font-size: 14px;
  font-weight: 700;

  letter-spacing: -0.02em;
}

.normal-text,
.done-text {
  position: absolute;

  left: 0;
  top: 0;

  transition:
    transform 0.5s cubic-bezier(0.2, 1.2, 0.3, 1),
    opacity 0.3s ease;
}

.normal-text {
  transform: translateY(0);
  opacity: 1;
}

.done-text {
  transform: translateY(25px);
  opacity: 0;
}

/* ═══════════════════════════════
   ARROW
═══════════════════════════════ */

.arrow {
  width: 31px;
  height: 31px;

  display: grid;
  place-items: center;

  border-radius: 10px;

  color: rgba(255, 255, 255, 0.65);

  background: rgba(255, 255, 255, 0.07);

  font-size: 17px;

  transition:
    transform 0.4s cubic-bezier(0.2, 1.2, 0.3, 1),
    background 0.25s ease,
    color 0.25s ease;
}

/* ═══════════════════════════════
   HOVER
═══════════════════════════════ */

.send:hover {
  transform: translateY(-4px);

  box-shadow:
    0 22px 40px rgba(0, 0, 0, 0.45),
    0 0 0 1px rgba(255, 255, 255, 0.05),
    inset 0 1px 0 rgba(255, 255, 255, 0.16);
}

.send:hover::before {
  opacity: 1;
}

.send:hover .shine {
  left: 150%;
}

.send:hover .icon-box {
  transform: translateY(-2px) rotate(-5deg) scale(1.08);
}

.send:hover .arrow {
  transform: translate(3px, -3px) rotate(3deg);

  color: #fff;

  background: rgba(255, 255, 255, 0.12);
}

/* ═══════════════════════════════
   PARTICULAS
═══════════════════════════════ */

.particle {
  position: absolute;

  width: 4px;
  height: 4px;

  border-radius: 50%;

  background: #fff;

  opacity: 0;

  pointer-events: none;

  transition:
    transform 0.6s cubic-bezier(0.2, 0.9, 0.2, 1),
    opacity 0.25s ease;
}

.p1 {
  left: 10px;
  top: 8px;
}
.p2 {
  right: 15px;
  top: 5px;
}
.p3 {
  left: 5px;
  bottom: 8px;
}
.p4 {
  right: 5px;
  bottom: 12px;
}
.p5 {
  left: 45px;
  top: -2px;
}
.p6 {
  right: 45px;
  bottom: -2px;
}

.send:hover .particle {
  opacity: 0.7;
}

.send:hover .p1 {
  transform: translate(-8px, -10px);
}

.send:hover .p2 {
  transform: translate(9px, -8px);
}

.send:hover .p3 {
  transform: translate(-10px, 8px);
}

.send:hover .p4 {
  transform: translate(10px, 7px);
}

.send:hover .p5 {
  transform: translate(-3px, -12px);
}

.send:hover .p6 {
  transform: translate(5px, 11px);
}

/* ═══════════════════════════════
   CLICK / PRESIONAR
═══════════════════════════════ */

.send:active {
  transform: scale(0.96);
}

/* ═══════════════════════════════
   ESTADO ENVIADO
═══════════════════════════════ */

.send-input:checked + .send {
  color: #000;

  background: #fff;

  border-color: #fff;

  box-shadow:
    0 18px 35px rgba(0, 0, 0, 0.3),
    inset 0 1px 0 #fff;
}

/* icono */

.send-input:checked + .send .icon-box {
  color: #fff;
  background: #000;

  transform: scale(1.08) rotate(0deg);
}

/* avión despega */

.send-input:checked + .send .plane {
  opacity: 0;

  transform: translate(18px, -18px) rotate(30deg) scale(0.4);
}

/* check aparece */

.send-input:checked + .send .check {
  opacity: 1;

  transform: scale(1) rotate(0);
}

/* texto */

.send-input:checked + .send .normal-text {
  opacity: 0;

  transform: translateY(-25px);
}

.send-input:checked + .send .done-text {
  opacity: 1;

  transform: translateY(0);
}

/* flecha */

.send-input:checked + .send .arrow {
  color: #fff;

  background: #000;

  transform: rotate(45deg) scale(0.9);
}

/* ═══════════════════════════════
   ANILLO DE ENERGÍA
═══════════════════════════════ */

.ring {
  position: absolute;

  inset: -5px;

  border-radius: 23px;

  border: 1px solid #fff;

  opacity: 0;
  transform: scale(0.8);

  pointer-events: none;
}

.send-input:checked + .send .ring {
  animation: ring-pop 0.7s ease-out;
}

@keyframes ring-pop {
  0% {
    opacity: 0.8;
    transform: scale(0.95);
  }

  100% {
    opacity: 0;
    transform: scale(1.18);
  }
}

/* ═══════════════════════════════
   PARTICULAS AL ENVIAR
═══════════════════════════════ */

.send-input:checked + .send .particle {
  opacity: 1;
}

.send-input:checked + .send .p1 {
  transform: translate(-18px, -15px);
}

.send-input:checked + .send .p2 {
  transform: translate(18px, -13px);
}

.send-input:checked + .send .p3 {
  transform: translate(-18px, 14px);
}

.send-input:checked + .send .p4 {
  transform: translate(18px, 15px);
}

.send-input:checked + .send .p5 {
  transform: translate(-8px, -20px);
}

.send-input:checked + .send .p6 {
  transform: translate(8px, 20px);
}

/* ═══════════════════════════════
   FOCUS
═══════════════════════════════ */

.send-input:focus-visible + .send {
  outline: 2px solid #fff;
  outline-offset: 4px;
}

/* ═══════════════════════════════
   REDUCIR ANIMACIONES
═══════════════════════════════ */

@media (prefers-reduced-motion: reduce) {
  .send,
  .send *,
  .shine,
  .ring {
    animation: none !important;
    transition: none !important;
  }
}
